const sourcePayload = $input.first()?.json || {};
const rows = Array.isArray(sourcePayload.results) ? sourcePayload.results : [];
const seen = new Set();
const dropQuery = /^(utm_|fbclid$|gclid$|mc_|ref$|source$)/i;
function canonicalise(value) { try { const url = new URL(value); url.hash = ''; for (const key of [...url.searchParams.keys()]) if (dropQuery.test(key)) url.searchParams.delete(key); url.searchParams.sort(); return `${url.origin}${url.pathname.replace(/\/$/, '')}${url.search}`; } catch { return null; } }
const jobs = [];
for (const raw of rows) {
  const route = raw.redirect_url || raw.job_url || raw.url || '';
  const canonicalUrl = canonicalise(route);
  const title = String(raw.title || '').trim();
  const company = String(raw.company?.display_name || raw.company || '').trim();
  if (!title || !company || !canonicalUrl || /linkedin\.com\/jobs/i.test(route) || seen.has(canonicalUrl)) continue;
  seen.add(canonicalUrl);
  jobs.push({ source: 'adzuna', source_record_id: raw.id ? String(raw.id) : canonicalUrl, canonical_url: canonicalUrl, application_route: route, application_route_type: 'Adzuna listing', listing_verification: 'Aggregator listing; confirm the original employer route and requirements before applying.', title, company, location: raw.location?.display_name || '', description: raw.description || '', salary: { min: raw.salary_min ?? null, max: raw.salary_max ?? null, currency: 'AUD' }, work_type: raw.contract_type || raw.category?.label || '', remote: /remote|work from home|hybrid/i.test(`${raw.title || ''} ${raw.description || ''}`), lane: 'core', posted_at: raw.created || null, screening_score: null, fit: 'Review', matched_terms: [], evidence: [], gaps: [], requirements_to_confirm: ['Confirm the original employer listing, closing date, location, work rights, licences, clearances, and roster.'], confidence: null, needs_human_review: true });
}
return [{ json: { jobs } }];
